pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address to, uint256 v, bool shouldFail) public {
        TransferFromRecorder rec = new TransferFromRecorder(shouldFail);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vs = new uint256[](1);
        vs[0] = v;

        bool ok;
        bool returned;
        try c.transfer(from, address(rec), tos, vs) returns (bool r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
        }

        assertTrue(ok == !shouldFail);
    }
}

contract TransferFromRecorder {
    bool public immutable shouldFail;

    constructor(bool _shouldFail) {
        shouldFail = _shouldFail;
    }

    function transferFrom(address /*from*/, address /*to*/, uint256 /*amount*/) external returns (bool) {
        if (shouldFail) {
            revert();
        }
        return true;
    }
}
